/* cppi::13f8f1f8d55fb6f2c66c535bba4490349f58efa7be6f95270dccfde06160b74e */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-24' and business_date <= date '2025-06-24' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

/* cppi::76cb335f7c4b486af273adce6174832fef042d509a20523ddfcaae5e267ddc25 */
/* QuickSight dec5ddd2-b2bf-491c-94be-90fb1eca1b18 */
SELECT "business_date", "year", "from_currency", "to_currency", "rate_type_code", "source", "bid_price", "ask_price", "mid_price", "factor", "inverse_quoted", "last_update_date", "vendor_file_name", "arrival_time"
FROM (SELECT *
FROM market.refinitiv_exchange_rates_wmr) AS "FX Rates - EUR, GBP, USD (PROD)"

